  const parsedOffset = offset ? parseInt(offset, 10) : undefined;

  if (limit && (!parsedLimit || parsedLimit < 0 || parsedLimit > 100)) {
    return res.status(400).json({ error: 'Invalid limit parameter (0-100)' });
  }

  if (offset && (!parsedOffset || parsedOffset < 0)) {
    return res.status(400).json({ error: 'Invalid offset parameter (must be >= 0)' });
  }

  req.validated = { limit: parsedLimit, offset: parsedOffset };
